def propagate(grid, dr, dc):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    rrange = range(h) if dr>=0 else range(h-1,-1,-1)
    crange = range(w) if dc>=0 else range(w-1,-1,-1)
    for r in rrange:
        for c in crange:
            pr,pc=r-dr,c-dc
            if 0<=pr<h and 0<=pc<w and grid[r][c]!=grid[pr][pc]:
                out[r][c]=1
    return out
